INSERT INTO `pages` VALUES (1,NULL,'Azienda','azienda','Dal 1981, calzature di qualità nel distretto del Cuoio.','Jaguar nasce nel comune di Castelfranco di Sotto, in provincia di Pisa, nel 1981: i fratelli Martone, Rocco e Marciano, decidono di avventurarsi nel mondo calzaturiero dando vita a un piccolo laboratorio artigianale a carattere familiare.\n\nDopo aver affrontato le prime stagioni di difficoltà e di duro lavoro, l’azienda riesce ad affermarsi progressivamente nel panorama internazionale, diventando sinonimo di elevata qualità al giusto prezzo.\n\nL’utilizzo di materie prime di pregio provenienti dallo stesso comprensorio del Cuoio, la manodopera specializzata nell’assemblaggio e nella rifinitura e uno stile originale e in continua evoluzione consentono all’azienda di soddisfare le richieste di una clientela sempre più vasta, differenziata ed esigente.\n\nNel 1994 Jaguar si trasferisce a Santa Maria a Monte e amplia notevolmente la propria produzione industriale. Negli anni Novanta prende avvio una solida collaborazione con marchi internazionali come Tommy Hilfiger, Max Mara, Penny Black, Strenesse e Donald J. Pliner.\n\nSuccessivamente viene lanciato il marchio Sabrina Martone.','pages/galleries/imported/company-001.webp','Azienda | Calzaturificio Jaguar','La storia del Calzaturificio Jaguar: calzature di qualità realizzate in Italia dal 1981.',1,10,'2026-11-12 07:50:24','2026-11-20 10:47:21'),(12,NULL,'Collezione Estate ’15','collezione-estate-15',NULL,NULL,'pages/galleries/imported/collection-01-001.webp','Collezione Estate ’15',NULL,1,20,'2026-11-20 10:42:31','2026-11-20 10:46:07'),(13,NULL,'Collezione Inverno \'15-\'16','collezione-inverno-15-16',NULL,NULL,'pages/galleries/imported/collection-02-001.webp','Collezione Inverno \'15-\'16',NULL,1,30,'2026-11-20 10:42:32','2026-11-20 10:46:08'),(14,NULL,'Nuova Collezione','nuova-collezione',NULL,NULL,'pages/galleries/imported/collection-03-001.webp','Nuova Collezione',NULL,1,40,'2026-11-20 10:42:34','2026-11-20 10:46:11');
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
