INSERT INTO `settings` VALUES (1,'company_name','Calzaturificio Jaguar','2026-11-12 07:50:24','2026-11-12 09:50:32'),(2,'hero_title','Una storia di calzature italiane dal 1981.','2026-11-12 07:50:24','2026-11-20 10:42:31'),(3,'hero_subtitle','Qualità, ricerca e manifattura nel distretto del Cuoio.','2026-11-12 07:50:24','2026-11-20 10:42:31'),(4,'logo','settings/logo/jaguar.png','2026-11-12 08:28:13','2026-11-20 11:56:11'),(5,'hero_fallback','settings/hero_fallback/imported-hero.webp','2026-11-12 08:28:13','2026-11-12 08:28:13'),(6,'homepage_intro_title','Esperienza e manifattura italiana.','2026-11-20 10:42:31','2026-11-20 10:42:31'),(7,'homepage_intro_text','Fondata nel 1981 a Castelfranco di Sotto dai fratelli Rocco e Marciano Martone come laboratorio artigianale a conduzione familiare, Jaguar si è affermata per la qualità, i materiali del comprensorio del Cuoio e la cura dell’assemblaggio e della rifinitura. Dal 1994 ha sede a Santa Maria a Monte e firma le proprie collezioni con il marchio Sabrina Martone.','2026-11-20 10:42:31','2026-11-20 10:42:31');
